update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[{"label":"Location","value":"Raa Atoll, Northern Maldives"},{"label":"Island Type","value":"Inhabited Local Island"},{"label":"Population","value":"Approximately 1,800 residents"},{"label":"Size","value":"1.5 km long, 0.9 km wide"},{"label":"Distance from Male","value":"160 km"},{"label":"Transfer Options","value":"Seaplane or domestic flight + speedboat"},{"label":"Known For","value":"Authentic culture, pristine beaches, excellent snorkeling"},{"label":"Best For","value":"Cultural enthusiasts, beach lovers, snorkelers, authentic travelers"}],"island_overview":["Alifushi Island is an authentic local island in Raa Atoll that offers visitors a genuine glimpse into traditional Maldivian life. This charming island combines natural beauty with an authentic atmosphere, providing an ideal destination for travelers seeking real cultural experiences and pristine natural splendor.","Known for its pristine beaches, crystal-clear lagoons, and excellent house reef, Alifushi provides wonderful opportunities for snorkeling, swimming, and marine exploration. The island''s authentic community embraces visitors with traditional Maldivian warmth and shares their genuine way of life with sincere hospitality.","What makes Alifushi special is its authentic beauty and traditional natural setting. Visitors can enjoy pristine beaches, explore diverse marine life, and experience genuine island culture while staying in comfortable accommodations that showcase the authentic Maldivian lifestyle."],"island_sections":[{"heading":"Location & Map","paragraphs":["Alifushi Island is strategically located in the northern part of Raa Atoll, approximately 160 kilometers from Male. This location provides an authentic and genuine experience while maintaining good accessibility to the capital and international airport through various transfer options.","The island''s positio