update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[{"label":"Location","value":"Raa Atoll, Northern Maldives"},{"label":"Island Type","value":"Inhabited Local Island"},{"label":"Population","value":"Approximately 1,400 residents"},{"label":"Size","value":"1.5 km long, 0.9 km wide"},{"label":"Distance from Male","value":"155 km"},{"label":"Transfer Options","value":"Seaplane or domestic flight + speedboat"},{"label":"Known For","value":"Spectacular nature, magnificent beaches, excellent snorkeling"},{"label":"Best For","value":"Nature enthusiasts, beach lovers, snorkelers, adventure seekers"}],"island_overview":["Rasmaadhoo Island is a spectacular local island in Raa Atoll that offers visitors an extraordinary glimpse into traditional Maldivian life. This magnificent island combines natural beauty with a remarkable atmosphere, providing an ideal destination for travelers seeking outstanding cultural experiences and breathtaking tropical surroundings.","Known for its exceptional beaches, spectacular coral reefs, and excellent marine biodiversity, Rasmaadhoo provides remarkable opportunities for snorkeling, swimming, and underwater exploration. The island''s extraordinary community embraces visitors with traditional Maldivian warmth and shares their magnificent way of life with spectacular hospitality.","What makes Rasmaadhoo special is its spectacular natural environment and extraordinary island setting. Visitors can enjoy magnificent beaches, explore rich marine ecosystems, and experience remarkable island culture while staying in comfortable accommodations that showcase the spectacular Maldivian lifestyle."],"island_sections":[{"heading":"Location & Map","paragraphs":["Rasmaadhoo Island is magnificently located in the northern part of Raa Atoll, approximately 155 kilometers from Male. This location provides a spectacular and extraordinary experience while maintaining good accessibility to the capital and international airport through various transfer options.","The island''s position offers excellent protection from strong currents while providing access to magnificent coral reefs and diverse marine ecosystems. Its location in the atoll makes it an ideal base for exploring the natural beauty and cultural richness of Raa Atoll in its most spectacular form."]},{"heading":"Rasmaadhoo: Spectacular Paradise & Marine Excellence","paragraphs":["Rasmaadhoo Island is blessed with exceptional natural beauty, featuring magnificent white sand beaches, crystal-clear turquoise waters, and one of the most spectacular marine environments in Raa Atoll. The island offers perfect conditions for beach relaxation and marine exploration in an extraordinary, breathtaking setting."]},{"heading":"Magnificent White Sand Beaches","paragraphs":["Rasmaadhoo features spectacular white sand beaches with gentle slopes and calm waters, perfect for swimming, sunbathing, and extraordinary beach activities."]},{"heading":"Spectacular House Reef Snorkeling","paragraphs":["The island''s house reef is easily accessible from the beach and offers remarkable snorkeling with diverse marine life and colorful coral formations."]},{"heading":"Extraordinary Island Community","paragraphs":["Experience the remarkable spirit of traditional island life with friendly locals and spectacular Maldivian culture in an extraordinary community setting."]},{"heading":"Breathtaking Sandbank Adventures","paragraphs":["Explore nearby uninhabited sandbanks and magnificent islands around Rasmaadhoo for spectacular tropical paradise experiences with rich marine life."]},{"heading":"Beach Features","paragraphs":["Rasmaadhoo''s coastal highlights include:"]},{"heading":"Marine Environment","paragraphs":["The waters around Rasmaadhoo feature:"]},{"heading":"Activities & Experiences","paragraphs":["Rasmaadhoo offers a perfect blend of marine adventures, cultural experiences, and spectacular activities. The island''s extraordinary environment and remarkable atmosphere provide ideal conditions for various activities in a magnificent, breathtaking setting."]},{"heading":"Spectacular House Reef Snorkeling","paragraphs":["Explore the remarkable house reef directly from the beach, featuring colorful corals, tropical fish, and excellent underwater visibility in spectacular waters."]},{"heading":"Scuba Diving Excursions","paragraphs":["Discover nearby magnificent dive sites with professional dive operators offering guided dives and certification courses in spectacular marine environments."]},{"heading":"Island Hopping Adventures","paragraphs":["Visit nearby islands, magnificent sandbanks, and discover the natural beauty of Raa Atoll with extraordinary exploration opportunities."]},{"heading":"Traditional Fishing","paragraphs":["Experience authentic Maldivian fishing techniques with local fishermen during sunset and night fishing trips in spectacular community settings."]},{"heading":"Extraordinary Cultural Immersion","paragraphs":["Learn about local traditions, participate in community activities, and experience spectacular Maldivian island life with remarkable cultural exchanges."]},{"heading":"Sunset Cruises","paragraphs":["Enjoy magnificent sunset cruises around the atoll, often combined with dolphin watching and traditional dhoni sailing in spectacular waters."]},{"heading":"Community Life & Culture","paragraphs":["Rasmaadhoo is home to approximately 1,400 residents who maintain traditional Maldivian ways of life while embracing sustainable tourism. The island''s community is known for their exceptional friendliness, hospitality, and spectacular cultural traditions that create an extraordinary atmosphere for visitors."]},{"heading":"Island Life","paragraphs":["Daily life on Rasmaadhoo follows traditional patterns centered around fishing, family, and community activities. The island maintains a spectacular atmosphere where visitors can experience remarkable Maldivian culture and customs in their most extraordinary, breathtaking setting."]},{"heading":"Local Traditions","paragraphs":["The community preserves traditional Maldivian practices including traditional music, dance, handicrafts, and fishing techniques. Visitors can observe and often participate in cultural activities and celebrations in this spectacular island environment."]},{"heading":"Sustainable Tourism","paragraphs":["Rasmaadhoo has embraced sustainable tourism practices that benefit the local community while preserving the island''s natural environment and spectacular cultural heritage for future generations to experience and enjoy."]}],"island_faqs":[{"question":"How do I get to Rasmaadhoo Island?","answer":"Regular ferry services are also available from Male and nearby islands in Raa Atoll."},{"question":"What is the best time to visit Rasmaadhoo?","answer":"The best time to visit Rasmaadhoo is during the dry season from December to April when weather conditions are most favorable for beach activities and water sports. However, the island can be visited year-round with the wet season offering fewer crowds and a more spectacular local atmosphere."},{"question":"What accommodation options are available on Rasmaadhoo?","answer":"Rasmaadhoo offers various accommodations including spectacular guesthouses and beachfront properties. Most accommodations offer air conditioning, private bathrooms, and meal packages in an extraordinary setting."},{"question":"What makes Rasmaadhoo''s environment special?","answer":"Rasmaadhoo is known for its spectacular and extraordinary natural environment. The island maintains traditional Maldivian cultural practices while offering a remarkable atmosphere perfect for nature exploration. Visitors can experience outstanding cultural exchanges and participate in spectacular community activities."}],"island_nearby_slugs":["rasgetheemu","ungoofaaru","vaadhoo","alifushi","angolhitheemu","dhuvaafaru","fainu","hulhudhuffaaru","inguraidhoo","innamaadhoo","kinolhas","maakurathu","maduvvaree","meedhoo"]}'::jsonb
